function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const CONFIG = {
  detectionUrl: 'https://httpbin.org/post',   // replace with real PII detection API
  downstreamUrl: 'https://httpbin.org/post', // replace with logging / CRM / warehouse endpoint
  detectionTimeoutMs: 15000,
  downstreamTimeoutMs: 10000,
  // fields that are always treated as potential PII
  piiCandidates: ['email', 'phone', 'ssn', 'nationalId', 'address', 'name', 'firstName', 'lastName', 'dob', 'creditCard'],
  // anonymization policy
  redactWith: '[REDACTED]',
  hashSalt: 'change-me-in-production',
  allowSimulation: true
};

const hook = ref('Webhook - Incoming Business Data');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const headers = hook.headers || {};
const errors = [];

if (!body || Object.keys(body).length === 0) errors.push('Request body is required');

const requestId = String(headers['x-request-id'] || body.requestId || ('req-' + Date.now())).slice(0, 64);
const source = String(body.source || 'unknown').slice(0, 64);

// Collect candidate values
const candidates = {};
for (const key of CONFIG.piiCandidates) {
  if (body[key] !== undefined && body[key] !== null && String(body[key]).trim() !== '') {
    candidates[key] = String(body[key]).trim();
  }
}
// also scan nested objects one level deep
for (const [k, v] of Object.entries(body)) {
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    for (const key of CONFIG.piiCandidates) {
      if (v[key] !== undefined && v[key] !== null && String(v[key]).trim() !== '') {
        candidates[k + '.' + key] = String(v[key]).trim();
      }
    }
  }
}

const valid = errors.length === 0;

let detectionUrl = CONFIG.detectionUrl;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  detectionUrl = 'https://httpbin.org/status/' + sim;
}

return [{
  json: {
    valid,
    errors,
    requestId,
    source,
    original: body,
    candidates,
    config: CONFIG,
    detectionUrl,
    downstreamUrl: CONFIG.downstreamUrl
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Validate & Extract');
const res = $input.first().json || {};
const statusCode = Number(res.statusCode) || 0;

let body = res.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}
if (!body || typeof body !== 'object') body = {};

// Build findings map. Real APIs return structured results;
// here we also apply simple regex heuristics as fallback.
const findings = {};
const candidates = ctx.candidates || {};

const patterns = {
  email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
  phone: /^[+\d][\d\s().-]{7,}$/,
  ssn: /^\d{3}-\d{2}-\d{4}$/,
  creditCard: /^\d{13,19}$/
};

for (const [field, value] of Object.entries(candidates)) {
  let score = 0.4;
  let type = 'unknown';
  const lower = field.toLowerCase();
  if (lower.includes('email') || patterns.email.test(value)) { score = 0.95; type = 'email'; }
  else if (lower.includes('phone') || patterns.phone.test(value)) { score = 0.9; type = 'phone'; }
  else if (lower.includes('ssn') || patterns.ssn.test(value)) { score = 0.99; type = 'ssn'; }
  else if (lower.includes('credit') || patterns.creditCard.test(value.replace(/\s/g, ''))) { score = 0.97; type = 'creditCard'; }
  else if (lower.includes('name')) { score = 0.7; type = 'name'; }
  else if (lower.includes('address')) { score = 0.75; type = 'address'; }
  else if (lower.includes('dob') || lower.includes('birth')) { score = 0.85; type = 'dob'; }

  // override with API result if present
  if (body.findings && body.findings[field]) {
    score = Number(body.findings[field].score) || score;
    type = body.findings[field].type || type;
  }

  findings[field] = { value, score, type, action: score >= 0.7 ? 'anonymize' : 'keep' };
}

return [{
  json: {
    requestId: ctx.requestId,
    source: ctx.source,
    original: ctx.original,
    candidates,
    findings,
    config: ctx.config,
    detectionStatus: statusCode,
    detectionOk: statusCode >= 200 && statusCode < 300,
    downstreamUrl: ctx.downstreamUrl
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Parse Detection Results');
const cfg = ctx.config;
const findings = ctx.findings || {};
const original = JSON.parse(JSON.stringify(ctx.original || {}));

// simple deterministic hash (not crypto-grade, replace in production)
function simpleHash(str, salt) {
  let h = 0;
  const s = salt + String(str);
  for (let i = 0; i < s.length; i++) h = ((h << 5) - h) + s.charCodeAt(i) | 0;
  return 'h' + Math.abs(h).toString(16).padStart(8, '0');
}

function setPath(obj, path, value) {
  const parts = path.split('.');
  let cur = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    if (!cur[parts[i]] || typeof cur[parts[i]] !== 'object') cur[parts[i]] = {};
    cur = cur[parts[i]];
  }
  cur[parts[parts.length - 1]] = value;
}

const changes = [];
const anonymized = JSON.parse(JSON.stringify(original));

for (const [field, meta] of Object.entries(findings)) {
  if (meta.action !== 'anonymize') continue;
  let newVal;
  if (meta.type === 'email') {
    const parts = String(meta.value).split('@');
    newVal = simpleHash(parts[0], cfg.hashSalt) + '@' + (parts[1] || 'redacted.local');
  } else if (meta.type === 'phone') {
    newVal = '***-***-' + String(meta.value).replace(/\D/g, '').slice(-4);
  } else if (meta.type === 'ssn' || meta.type === 'creditCard') {
    newVal = cfg.redactWith;
  } else {
    newVal = simpleHash(meta.value, cfg.hashSalt);
  }
  setPath(anonymized, field, newVal);
  changes.push({ field, type: meta.type, score: meta.score, from: meta.value, to: newVal });
}

return [{
  json: {
    requestId: ctx.requestId,
    source: ctx.source,
    original,
    anonymized,
    findings,
    changes,
    config: cfg,
    detectionOk: ctx.detectionOk,
    downstreamUrl: ctx.downstreamUrl
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Apply Anonymization');
const downstream = $input.first().json || {};
const downstreamStatus = Number(downstream.statusCode) || 0;

const audit = {
  requestId: ctx.requestId,
  source: ctx.source,
  timestamp: new Date().toISOString(),
  fieldsExamined: Object.keys(ctx.findings || {}).length,
  fieldsAnonymized: (ctx.changes || []).length,
  changes: ctx.changes || [],
  detectionOk: ctx.detectionOk,
  downstreamOk: downstreamStatus >= 200 && downstreamStatus < 300,
  downstreamStatus
};

return [{
  json: {
    requestId: ctx.requestId,
    anonymized: ctx.anonymized,
    audit,
    config: ctx.config
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Build Audit Trail');

const httpStatus = ctx.audit && ctx.audit.detectionOk === false ? 502 : 200;

const body = {
  status: httpStatus === 200 ? 'anonymized' : 'partial_failure',
  requestId: ctx.requestId,
  data: ctx.anonymized,
  audit: {
    fieldsExamined: ctx.audit.fieldsExamined,
    fieldsAnonymized: ctx.audit.fieldsAnonymized,
    downstreamOk: ctx.audit.downstreamOk,
    timestamp: ctx.audit.timestamp
  }
};

return [{
  json: {
    httpStatus,
    body,
    requestId: ctx.requestId
  }
}];
